import { CommonModule, isPlatformBrowser } from '@angular/common';
import {
	AfterViewInit,
	ChangeDetectionStrategy,
	ChangeDetectorRef,
	Component,
	ElementRef,
	Inject,
	Input,
	OnDestroy,
	PLATFORM_ID,
	QueryList,
	Renderer2,
	ViewChild,
	ViewChildren,
	WritableSignal,
	computed,
	effect,
	signal,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

const PIN_BREAKPOINT = '(min-width: 992px)';
export interface ServiceScrollerItem {
	number: string;
	key: string;
	image: string;
	alt?: string;

	title: string;
	subtitle?: string;
	description: string;
	price?: string;
	duration?: string;
	tags?: string[];
}
@Component({
	selector: 'app-services-scroller',
	standalone: true,
	imports: [CommonModule],
	templateUrl: './services-scroller.component.html',
	styleUrl: './services-scroller.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})

export class ServicesScrollerComponent implements AfterViewInit, OnDestroy {

	/** Angle (deg) between two consecutive dial numbers. */
	@Input() angleStep = 28;
services: ServiceScrollerItem[] = [];
	/** Extra scroll distance (in viewport heights) the section stays pinned for. */
	@Input() scrollDistance = 1;

	@ViewChild('pinPanel') private pinPanelRef?: ElementRef<HTMLDivElement>;
	@ViewChild('dial') private dialRef?: ElementRef<HTMLDivElement>;
	@ViewChildren('numberItem') private numberItems?: QueryList<ElementRef<HTMLDivElement>>;
	@ViewChild('imageEl') private imageRef?: ElementRef<HTMLImageElement>;
	@ViewChild('imageWrapper') private imageWrapperRef?: ElementRef<HTMLDivElement>;
	@ViewChild('rightContent') private rightContentRef?: ElementRef<HTMLDivElement>;

	readonly activeIndex = signal(0);
	readonly activeService = computed<ServiceScrollerItem | undefined>(
		() => this.services[this.activeIndex()],
	);

	/** The pinned dial layout only applies above the tablet breakpoint; below it renders a plain stacked list. */
	readonly pinEnabled: WritableSignal<boolean>;

	private readonly isBrowser: boolean;
	private frameRequested = false;
	private pinBreakpointQuery?: MediaQueryList;

	private readonly onScroll = () => this.scheduleUpdate();
	private readonly onResize = () => this.scheduleUpdate();
	private readonly onPinBreakpointChange = (event: MediaQueryListEvent) => {
		this.pinEnabled.set(event.matches);
	};

	constructor(
	private readonly hostRef: ElementRef<HTMLElement>,
	private readonly renderer: Renderer2,
	private readonly translate: TranslateService,
	private readonly cdr: ChangeDetectorRef,
	@Inject(PLATFORM_ID) platformId: Object,
) {
	this.isBrowser = isPlatformBrowser(platformId);

	this.pinEnabled = signal(
		this.isBrowser
			? window.matchMedia(PIN_BREAKPOINT).matches
			: true
	);
	
effect(() => {
		this.activeIndex();

		if (!this.isBrowser) {
			return;
		}

		this.restartEntranceAnimation();
	});
}
private loadServices(): void {
  this.translate
    .stream('SCROLLMENU.SERVICES')
    .subscribe((translations: any) => {

      this.services = this.serviceConfig.map((config) => {
        const service = translations?.[config.key];

        return {
          ...config,
          title: service?.TITLE ?? '',
          subtitle: service?.SUBTITLE ?? '',
          description: service?.DESCRIPTION ?? '',
          price: service?.PRICE ?? '',
          duration: service?.DURATION ?? '',
          tags: Array.isArray(service?.TAGS) ? service.TAGS : [],
        };
      });

      this.activeIndex.set(0);

      this.cdr.markForCheck();

      requestAnimationFrame(() => {
        this.applyScrollProgress();
        this.restartEntranceAnimation();
      });
    });
}
private readonly serviceConfig = [
	{
		key: 'BRANDING',
		number: '01',
		image: '/assets/images/services/branding.webp',
		alt: 'Branding and Rebranding',
	},
	{
		key: 'BRAND_GUARDIAN',
		number: '02',
		image: '/assets/images/services/brand-guardian.webp',
		alt: 'Brand Guardian',
	},
	{
		key: 'CUSTOM_WEBSITES',
		number: '03',
		image: '/assets/images/services/custom-websites.webp',
		alt: 'Custom Websites',
	},
	{
		key: 'ECOMMERCE',
		number: '04',
		image: '/assets/images/services/ecommerce.webp',
		alt: 'eCommerce Website Development',
	},
	{
		key: 'MAINTENANCE',
		number: '05',
		image: '/assets/images/services/maintenance.webp',
		alt: 'Website Maintenance and Support',
	},
];

	ngAfterViewInit(): void {
	if (!this.isBrowser) {
		return;
	}

	this.loadServices();

	this.pinBreakpointQuery = window.matchMedia(PIN_BREAKPOINT);
	this.pinBreakpointQuery.addEventListener(
		'change',
		this.onPinBreakpointChange
	);

	window.addEventListener('scroll', this.onScroll, { passive: true });
	window.addEventListener('resize', this.onResize, { passive: true });

	this.applyScrollProgress();
	this.restartEntranceAnimation();
}
	ngOnDestroy(): void {
		if (!this.isBrowser) {
			return;
		}

		window.removeEventListener('scroll', this.onScroll);
		window.removeEventListener('resize', this.onResize);
		this.pinBreakpointQuery?.removeEventListener('change', this.onPinBreakpointChange);
	}

	private scheduleUpdate(): void {
		if (this.frameRequested) {
			return;
		}

		this.frameRequested = true;
		requestAnimationFrame(() => {
			this.frameRequested = false;
			this.applyScrollProgress();
		});
	}

	// Emulates GSAP ScrollTrigger's `pin: true` with plain JS: the panel stays
	// `position: fixed` while the tall host section scrolls past it, then
	// settles to `position: absolute` at the host's bottom edge once the
	// section is fully scrolled through. CSS `position: sticky` can't be used
	// here — this site's global `body { overflow-x: hidden }` makes `body` a
	// scroll container, which becomes the containing block for sticky
	// descendants instead of the viewport, so sticky never engages.
	private applyScrollProgress(): void {
		if (!this.pinEnabled() || this.services.length === 0) {
			return;
		}

		const host = this.hostRef.nativeElement;
		const panel = this.pinPanelRef?.nativeElement;
		const viewportHeight = window.innerHeight;
		const scrollable = host.offsetHeight - viewportHeight;

		if (scrollable <= 0) {
			return;
		}

		const rect = host.getBoundingClientRect();

		if (panel) {
			if (rect.top > 0) {
				this.renderer.setStyle(panel, 'position', 'relative');
				this.renderer.removeStyle(panel, 'top');
				this.renderer.removeStyle(panel, 'left');
				this.renderer.removeStyle(panel, 'width');
			} else if (rect.bottom <= viewportHeight) {
				this.renderer.setStyle(panel, 'position', 'absolute');
				this.renderer.setStyle(panel, 'top', `${scrollable}px`);
				this.renderer.setStyle(panel, 'left', '0px');
				this.renderer.setStyle(panel, 'width', '100%');
			} else {
				this.renderer.setStyle(panel, 'position', 'fixed');
				this.renderer.setStyle(panel, 'top', '0px');
				this.renderer.setStyle(panel, 'left', `${rect.left}px`);
				this.renderer.setStyle(panel, 'width', `${rect.width}px`);
			}
		}

		const progress = clamp(-rect.top / scrollable, 0, 1);
		const rawIndex = progress * (this.services.length - 1);
		const index = Math.round(rawIndex);
		const rotation = -rawIndex * this.angleStep;

		if (this.dialRef) {
			this.renderer.setStyle(
				this.dialRef.nativeElement,
				'transform',
				`translateY(-50%) rotate(${rotation}deg)`,
			);
		}

		this.numberItems?.forEach((ref, i) => {
			const angle = i * this.angleStep;
			this.renderer.setStyle(
				ref.nativeElement,
				'transform',
				`rotate(${angle}deg) translateX(var(--dial-radius, 350px)) rotate(${-angle}deg) translate(-50%, -50%) rotate(${-rotation}deg)`,
			);
		});

		if (this.imageRef) {
			this.renderer.setStyle(
				this.imageRef.nativeElement,
				'transform',
				`translateY(${-8 * progress}%)`,
			);
		}

		if (this.activeIndex() !== index) {
			this.activeIndex.set(index);
		}
	}

	private restartEntranceAnimation(): void {
		const elements: (HTMLElement | undefined)[] = [
			this.rightContentRef?.nativeElement,
			this.imageWrapperRef?.nativeElement,
			this.imageRef?.nativeElement,
		];

		for (const el of elements) {
			if (!el) {
				continue;
			}

			this.renderer.removeClass(el, 'is-revealing');
			// Force a reflow so the animation restarts on the next class toggle.
			void el.offsetWidth;
			this.renderer.addClass(el, 'is-revealing');
		}
	}
}

function clamp(value: number, min: number, max: number): number {
	return Math.min(Math.max(value, min), max);
}
