import { isPlatformBrowser } from '@angular/common';
import {
	AfterViewInit,
	ChangeDetectionStrategy,
	ChangeDetectorRef,
	Component,
	DOCUMENT,
	ElementRef,
	Inject,
	PLATFORM_ID,
	ViewChild,
} from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { LucideAngularModule } from 'lucide-angular';
import { TranslationService } from '../../../core/services/translation.service';
import { environment } from '../../../../environments/environment';

@Component({
	selector: 'app-show-reel',
	imports: [TranslateModule, LucideAngularModule],
	templateUrl: './show-reel.component.html',
	styleUrl: './show-reel.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ShowReelComponent implements AfterViewInit {
	baseUrl: string;

	@ViewChild('modalDesktopVideo')
	modalDesktopVideo?: ElementRef<HTMLVideoElement>;

	@ViewChild('modalMobileVideo')
	modalMobileVideo?: ElementRef<HTMLVideoElement>;
	private isVideoModalOpen = false;
	@ViewChild('videoModal')
	videoModal?: ElementRef<HTMLDivElement>;
	@ViewChild('desktopVideo') desktopVideo?: ElementRef<HTMLVideoElement>;
	@ViewChild('mobileVideo') mobileVideo?: ElementRef<HTMLVideoElement>;
	@ViewChild('videoWrapper') videoWrapper?: ElementRef<HTMLDivElement>;
	@ViewChild('videoFrame') videoFrame?: ElementRef<HTMLDivElement>;
	@ViewChild('videoHoverBtn') videoHoverBtn?: ElementRef<HTMLDivElement>;
	@ViewChild('videoHoverBtnInner') videoHoverBtnInner?: ElementRef<HTMLDivElement>;
	@ViewChild('canvas', { static: true })
	containerRef!: ElementRef<HTMLDivElement>;

	ngAfterViewInit(): void {
		if (!isPlatformBrowser(this.platformId)) {
			return;
		}

		this.setupVideoHoverButton();
	}

	constructor(
		public translationService: TranslationService,
		private cdr: ChangeDetectorRef,
		@Inject(DOCUMENT) private document: Document,
		@Inject(PLATFORM_ID) private platformId: Object,
	) {
		this.baseUrl = environment.url;
	}

	private backgroundVideosWerePlaying = {
		desktop: false,
		mobile: false,
	};

	playVideoInModal(): void {
		if (!isPlatformBrowser(this.platformId)) return;

		const desktopVideo = this.desktopVideo?.nativeElement;
		const mobileVideo = this.mobileVideo?.nativeElement;

		const modalDesktopVideo = this.modalDesktopVideo?.nativeElement;
		const modalMobileVideo = this.modalMobileVideo?.nativeElement;

		const modal = this.videoModal?.nativeElement;

		if (!modal || !modalDesktopVideo || !modalMobileVideo) return;

		// Remember background state
		this.backgroundVideosWerePlaying.desktop = !!desktopVideo && !desktopVideo.paused;

		this.backgroundVideosWerePlaying.mobile = !!mobileVideo && !mobileVideo.paused;

		// ❌ STOP HERO VIDEOS
		desktopVideo?.pause();
		mobileVideo?.pause();

		// Open modal
		modal.classList.add('is-open');
		this.isVideoModalOpen = true;

		// Determine screen
		const isDesktop = window.matchMedia('(min-width: 768px)').matches;

		// ✅ ONLY MODAL VIDEO PLAYS
		const activeModalVideo = isDesktop ? modalDesktopVideo : modalMobileVideo;

		const inactiveModalVideo = isDesktop ? modalMobileVideo : modalDesktopVideo;

		// Stop other modal video
		inactiveModalVideo.pause();
		inactiveModalVideo.currentTime = 0;

		// Start modal video
		activeModalVideo.currentTime = 0;
		activeModalVideo.muted = false;
		activeModalVideo.volume = 1;

		activeModalVideo.play().catch((err) => {
			console.error('Modal video play error:', err);
		});
	}
	closeVideoModal(): void {
		if (!isPlatformBrowser(this.platformId)) return;

		const desktopVideo = this.desktopVideo?.nativeElement;
		const mobileVideo = this.mobileVideo?.nativeElement;

		const modalDesktopVideo = this.modalDesktopVideo?.nativeElement;
		const modalMobileVideo = this.modalMobileVideo?.nativeElement;

		const modal = this.videoModal?.nativeElement;

		if (!modal) return;

		// ❌ STOP MODAL VIDEOS
		modalDesktopVideo?.pause();
		modalMobileVideo?.pause();

		if (modalDesktopVideo) {
			modalDesktopVideo.currentTime = 0;
		}

		if (modalMobileVideo) {
			modalMobileVideo.currentTime = 0;
		}

		// Close modal
		modal.classList.remove('is-open');
		this.isVideoModalOpen = false;

		// ✅ Resume hero video only if it was playing before
		if (this.backgroundVideosWerePlaying.desktop) {
			desktopVideo?.play().catch(() => {});
		}

		if (this.backgroundVideosWerePlaying.mobile) {
			mobileVideo?.play().catch(() => {});
		}

		this.backgroundVideosWerePlaying.desktop = false;
		this.backgroundVideosWerePlaying.mobile = false;
	}

	private hoverBtnTargetX = 0;
	private hoverBtnTargetY = 0;
	private hoverBtnCurrentX = 0;
	private hoverBtnCurrentY = 0;
	private hoverBtnRafId: number | null = null;

	private readonly handleVideoMouseMove = (event: MouseEvent): void => {
		const frame = this.videoFrame?.nativeElement;

		const btn = this.videoHoverBtn?.nativeElement;

		if (!frame || !btn) return;

		const rect = frame.getBoundingClientRect();

		this.hoverBtnTargetX = event.clientX - rect.left - btn.offsetWidth / 2;

		this.hoverBtnTargetY = event.clientY - rect.top - btn.offsetHeight / 2;
	};
	private setupVideoHoverButton(): void {
		const videos = [this.desktopVideo?.nativeElement, this.mobileVideo?.nativeElement];

		videos.forEach((video) => {
			if (!video) return;

			video.addEventListener('mouseenter', this.handleVideoMouseEnter);

			video.addEventListener('mousemove', this.handleVideoMouseMove);

			video.addEventListener('mouseleave', this.handleVideoMouseLeave);
		});

		this.videoHoverBtnInner?.nativeElement.addEventListener(
			'animationend',
			this.handleHoverBtnAnimationEnd,
		);
	}

	private readonly handleVideoMouseEnter = (event: MouseEvent): void => {
		this.videoFrame?.nativeElement.classList.add('is-hovering');
		// Snap to the entry point immediately instead of gliding in from (0, 0)
		this.handleVideoMouseMove(event);
		this.hoverBtnCurrentX = this.hoverBtnTargetX;
		this.hoverBtnCurrentY = this.hoverBtnTargetY;
		this.startHoverBtnLoop();
	};

	private readonly handleVideoMouseLeave = (): void => {
		this.videoFrame?.nativeElement.classList.remove('is-hovering');
		if (this.hoverBtnRafId !== null) {
			cancelAnimationFrame(this.hoverBtnRafId);
			this.hoverBtnRafId = null;
		}
	};
	private readonly handleVideoClick = (): void => {
		const inner = this.videoHoverBtnInner?.nativeElement;
		if (!inner) return;

		// Drop out of the hover state immediately so the opacity:1 hover rule
		// doesn't pop the button back in right as the burst animation ends.
		this.videoFrame?.nativeElement.classList.remove('is-hovering');
		inner.classList.remove('is-clicking');
		void inner.offsetWidth; // restart the animation if clicked again mid-burst
		inner.classList.add('is-clicking');
	};

	private readonly handleHoverBtnAnimationEnd = (): void => {
		this.videoHoverBtnInner?.nativeElement.classList.remove('is-clicking');
	};

	private startHoverBtnLoop(): void {
		if (this.hoverBtnRafId !== null) return;

		const step = () => {
			this.hoverBtnCurrentX += (this.hoverBtnTargetX - this.hoverBtnCurrentX) * 0.25;
			this.hoverBtnCurrentY += (this.hoverBtnTargetY - this.hoverBtnCurrentY) * 0.25;
			const btn = this.videoHoverBtn?.nativeElement;
			if (btn) {
				btn.style.transform = `translate3d(${this.hoverBtnCurrentX}px, ${this.hoverBtnCurrentY}px, 0)`;
			}
			this.hoverBtnRafId = requestAnimationFrame(step);
		};

		this.hoverBtnRafId = requestAnimationFrame(step);
	}
}
